import { useState } from 'react';
import { JxTagInput, JxChip } from '@jinx-ui/react';

interface ArticleTagsPickerProps {
  label?: string;
  defaultTags?: string[];
  placeholder?: string;
  onChange?: (tags: string[]) => void;
}

export default function ArticleTagsPicker({
  label = 'Теги статьи',
  defaultTags = [],
  placeholder = 'Введите тег и нажмите Enter',
  onChange,
}: ArticleTagsPickerProps) {
  const [tags, setTags] = useState<string[]>(defaultTags);

  const update = (next: string[]) => {
    setTags(next);
    onChange?.(next);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
      <span className="jx-label">{label}</span>

      <JxTagInput
        ariaLabel={label}
        placeholder={placeholder}
        value={tags}
        onValueChange={update}
      />

      {tags.length > 0 && (
        <div
          role="list"
          aria-label="Выбранные теги"
          style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}
        >
          {tags.map((tag) => (
            <span role="listitem" key={tag}>
              <JxChip
                active
                removable
                onRemove={() => update(tags.filter((item) => item !== tag))}
              >
                {tag}
              </JxChip>
            </span>
          ))}
        </div>
      )}

      <span className="jx-input-help" style={{ color: 'var(--jx-text-3)' }}>
        {tags.length === 0 ? 'Тегов пока нет' : `Выбрано тегов: ${tags.length}`}
      </span>
    </div>
  );
}

